begin;
-- IHO 2025/103: 2025-26 onward. Supersedes former 61/2024 and 30/2025 attachments.
update official_general_timetable_profiles set source_decision_no='2025-103',source_decision_date='2025-10-14',source_url='https://dogm.meb.gov.tr/pdf/DersCizelgeleri/IHO_HDC_2025-103_KurulKarari_Uygulamali.pdf',source_page=2,updated_at=now() where school_type='IMAM_HATIP_ORTAOKULU' and program_variant='STANDARD' and active;
-- Replace changed standard rows only.
with q as(select p.id,p.grade_level from official_general_timetable_profiles p where p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant='STANDARD' and p.active),x as(select r.id,q.grade_level,c.name from official_general_timetable_rows r join q on q.id=r.profile_id join course_catalog c on c.id=r.course_id) delete from official_general_timetable_rows r using x where r.id=x.id and x.name in('Bilişim Teknolojileri ve Yazılım','Teknoloji ve Tasarım','Rehberlik ve Kariyer Planlama','Rehberlik ve Yönlendirme','Temel Dinî Bilgiler');
insert into course_catalog(name,category,active) values ('Rehberlik ve Yönlendirme','rehberlik',true),('Temel Dinî Bilgiler','zorunlu',true),('Beden Eğitimi ve Spor/Görsel Sanatlar/Müzik','zorunlu',true),('Beden Eğitimi, Oyun ve Müzik','uygulama',true),('Müziksel İşitme, Okuma ve Yazma','uygulama',true),('Türk Müziği Teori ve Uygulaması','uygulama',true),('Koro ve Repertuvar','uygulama',true),('Bireysel Çalgı Eğitimi','uygulama',true),('Bireysel Ses Eğitimi','uygulama',true),('Çalgı Toplulukları','uygulama',true),('Müzik Tarihi','uygulama',true),('Beden Eğitimi ve Sporun Temelleri','uygulama',true),('Ritim Eğitimi ve Halk Oyunları','uygulama',true),('Oyun ve Taktiksel Farkındalık','uygulama',true),('Çocuklarda Atletik Performans Uygulamaları','uygulama',true),('Kapsamlı Spor Eğitimi','uygulama',true) on conflict(name) do nothing;
with q as(select id,grade_level from official_general_timetable_profiles where school_type='IMAM_HATIP_ORTAOKULU' and program_variant='STANDARD' and active),d(g,n,h) as(values (5,'Bilişim Teknolojileri ve Yazılım',1),(6,'Bilişim Teknolojileri ve Yazılım',1),(7,'Teknoloji ve Tasarım',1),(8,'Teknoloji ve Tasarım',2),(5,'Rehberlik ve Yönlendirme',1),(6,'Rehberlik ve Yönlendirme',1),(7,'Rehberlik ve Yönlendirme',1),(8,'Rehberlik ve Yönlendirme',1),(6,'Temel Dinî Bilgiler',1),(7,'Temel Dinî Bilgiler',1)) insert into official_general_timetable_rows(profile_id,course_id,weekly_hours,category,source_page,constraints,active) select q.id,c.id,d.h,case when d.n='Rehberlik ve Yönlendirme' then 'rehberlik' else 'zorunlu' end,2,'{}',true from d join q on q.grade_level=d.g join course_catalog c on c.name=d.n;
-- Variant profiles: Hafızlık, Müzik, Spor, 40-hour language-intensive.
with v(program_variant,g,total,fixed,elective,freep,page,constraints) as(values ('HAFIZLIK',5,27,27,0,0,9,'{"rule":4}'::jsonb),('HAFIZLIK',6,27,27,0,0,9,'{"rule":4}'::jsonb),('HAFIZLIK',7,27,27,0,0,9,'{"rule":4}'::jsonb),('HAFIZLIK',8,36,34,2,0,9,'{"rule":4}'::jsonb),('MUZIK',5,42,31,0,11,10,'{"rule":5,"program_elective_hours":11}'::jsonb),('MUZIK',6,42,32,0,10,10,'{"rule":5,"program_elective_hours":10}'::jsonb),('MUZIK',7,42,32,0,10,10,'{"rule":5,"program_elective_hours":10}'::jsonb),('MUZIK',8,42,30,1,11,10,'{"rule":5,"program_elective_hours":11}'::jsonb),('SPOR',5,42,32,0,10,11,'{"rule":6,"program_elective_hours":10}'::jsonb),('SPOR',6,42,33,0,9,11,'{"rule":6,"program_elective_hours":9}'::jsonb),('SPOR',7,42,33,0,9,11,'{"rule":6,"program_elective_hours":9}'::jsonb),('SPOR',8,42,31,1,10,11,'{"rule":6,"program_elective_hours":10}'::jsonb),('DIL_YOGUN_40',5,40,30,1,9,4,'{"rule":3,"language_choice_hours":9}'::jsonb),('DIL_YOGUN_40',6,40,34,2,4,5,'{"rule":3,"language_choice_hours":4}'::jsonb),('DIL_YOGUN_40',7,40,34,2,4,5,'{"rule":3,"language_choice_hours":4}'::jsonb),('DIL_YOGUN_40',8,40,34,3,3,5,'{"rule":3,"language_choice_hours":3}'::jsonb)) insert into official_general_timetable_profiles(effective_academic_year,school_type,school_subtype,program_variant,grade_level,total_hours,fixed_hours,elective_hours,guidance_hours,free_activity_hours,source_decision_no,source_decision_date,source_url,source_page,applicability_status,constraints,active) select '2025-2026','IMAM_HATIP_ORTAOKULU','',v.program_variant,v.g,v.total,v.fixed,v.elective,0,v.freep,'2025-103','2025-10-14','https://dogm.meb.gov.tr/pdf/DersCizelgeleri/IHO_HDC_2025-103_KurulKarari_Uygulamali.pdf',v.page,'ACTIVE',v.constraints,true from v where not exists(select 1 from official_general_timetable_profiles p where p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant=v.program_variant and p.grade_level=v.g and p.active);
-- Rebuild variant rows idempotently.
delete from official_general_timetable_rows r using official_general_timetable_profiles p where r.profile_id=p.id and p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant in('HAFIZLIK','MUZIK','SPOR','DIL_YOGUN_40') and p.active;
with s as(select p.grade_level,c.name,r.weekly_hours from official_general_timetable_rows r join official_general_timetable_profiles p on p.id=r.profile_id join course_catalog c on c.id=r.course_id where p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant='STANDARD' and p.active and r.active),t as(select * from official_general_timetable_profiles where school_type='IMAM_HATIP_ORTAOKULU' and program_variant in('HAFIZLIK','MUZIK','SPOR','DIL_YOGUN_40') and active),x as(select t.id profile_id,s.name,s.weekly_hours from t join s on s.grade_level=t.grade_level where (t.program_variant='HAFIZLIK' and (t.grade_level=8 or(t.grade_level in(5,6,7) and s.name in('Türkçe','Matematik','Fen Bilimleri','Sosyal Bilgiler','Yabancı Dil','Din Kültürü ve Ahlak Bilgisi','Arapça','Rehberlik ve Yönlendirme')))) or (t.program_variant='MUZIK' and((t.grade_level in(5,6) and s.name not in('Beden Eğitimi ve Spor','Müzik','Bilişim Teknolojileri ve Yazılım')) or(t.grade_level=7 and s.name not in('Beden Eğitimi ve Spor','Müzik','Teknoloji ve Tasarım')) or(t.grade_level=8 and s.name in('Türkçe','Matematik','Fen Bilimleri','T.C. İnkılap Tarihi ve Atatürkçülük','Yabancı Dil','Din Kültürü ve Ahlak Bilgisi','Görsel Sanatlar','Rehberlik ve Yönlendirme','Kur’an-ı Kerim','Arapça','Peygamberimizin Hayatı')))) or (t.program_variant='SPOR' and((t.grade_level in(5,6) and s.name not in('Beden Eğitimi ve Spor','Bilişim Teknolojileri ve Yazılım')) or(t.grade_level=7 and s.name not in('Beden Eğitimi ve Spor','Teknoloji ve Tasarım')) or(t.grade_level=8 and s.name in('Türkçe','Matematik','Fen Bilimleri','T.C. İnkılap Tarihi ve Atatürkçülük','Yabancı Dil','Din Kültürü ve Ahlak Bilgisi','Görsel Sanatlar','Müzik','Rehberlik ve Yönlendirme','Kur’an-ı Kerim','Arapça','Peygamberimizin Hayatı')))) or (t.program_variant='DIL_YOGUN_40' and((t.grade_level=5 and s.name not in('Beden Eğitimi ve Spor','Görsel Sanatlar','Müzik','Bilişim Teknolojileri ve Yazılım')) or(t.grade_level=6 and s.name<>'Bilişim Teknolojileri ve Yazılım') or(t.grade_level=7 and s.name<>'Teknoloji ve Tasarım') or t.grade_level=8))) insert into official_general_timetable_rows(profile_id,course_id,weekly_hours,category,source_page,constraints,active) select x.profile_id,c.id,x.weekly_hours,case when x.name='Rehberlik ve Yönlendirme' then 'rehberlik' else 'zorunlu' end,2,'{}',true from x join course_catalog c on c.name=x.name;
insert into official_general_timetable_rows(profile_id,course_id,weekly_hours,category,source_page,constraints,active) select p.id,c.id,1,'zorunlu',9,'{"choose_one":["Beden Eğitimi ve Spor","Görsel Sanatlar","Müzik"]}',true from official_general_timetable_profiles p join course_catalog c on c.name='Beden Eğitimi ve Spor/Görsel Sanatlar/Müzik' where p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant='HAFIZLIK' and p.grade_level in(5,6,7) and p.active;
with d(g,n,h) as(values (5,'Beden Eğitimi, Oyun ve Müzik',1),(5,'Müziksel İşitme, Okuma ve Yazma',2),(5,'Türk Müziği Teori ve Uygulaması',1),(5,'Koro ve Repertuvar',1),(5,'Bireysel Çalgı Eğitimi',2),(5,'Bireysel Ses Eğitimi',1),(5,'Çalgı Toplulukları',2),(5,'Müzik Tarihi',1),(6,'Beden Eğitimi, Oyun ve Müzik',1),(6,'Müziksel İşitme, Okuma ve Yazma',1),(6,'Türk Müziği Teori ve Uygulaması',1),(6,'Koro ve Repertuvar',1),(6,'Bireysel Çalgı Eğitimi',2),(6,'Bireysel Ses Eğitimi',1),(6,'Çalgı Toplulukları',2),(6,'Müzik Tarihi',1),(7,'Beden Eğitimi, Oyun ve Müzik',1),(7,'Müziksel İşitme, Okuma ve Yazma',1),(7,'Türk Müziği Teori ve Uygulaması',1),(7,'Koro ve Repertuvar',1),(7,'Bireysel Çalgı Eğitimi',2),(7,'Bireysel Ses Eğitimi',1),(7,'Çalgı Toplulukları',2),(7,'Müzik Tarihi',1),(8,'Beden Eğitimi, Oyun ve Müzik',1),(8,'Müziksel İşitme, Okuma ve Yazma',1),(8,'Türk Müziği Teori ve Uygulaması',1),(8,'Koro ve Repertuvar',2),(8,'Bireysel Çalgı Eğitimi',2),(8,'Bireysel Ses Eğitimi',1),(8,'Çalgı Toplulukları',2),(8,'Müzik Tarihi',1)) insert into official_general_timetable_rows(profile_id,course_id,weekly_hours,category,source_page,constraints,active) select p.id,c.id,d.h,'uygulama',10,'{"program_pool":"MUZIK"}',true from d join official_general_timetable_profiles p on p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant='MUZIK' and p.grade_level=d.g and p.active join course_catalog c on c.name=d.n;
with d(g,n,h) as(values (5,'Beden Eğitimi ve Sporun Temelleri',1),(5,'Ritim Eğitimi ve Halk Oyunları',1),(5,'Oyun ve Taktiksel Farkındalık',2),(5,'Çocuklarda Atletik Performans Uygulamaları',2),(5,'Kapsamlı Spor Eğitimi',4),(6,'Beden Eğitimi ve Sporun Temelleri',1),(6,'Ritim Eğitimi ve Halk Oyunları',1),(6,'Oyun ve Taktiksel Farkındalık',2),(6,'Çocuklarda Atletik Performans Uygulamaları',2),(6,'Kapsamlı Spor Eğitimi',3),(7,'Beden Eğitimi ve Sporun Temelleri',1),(7,'Ritim Eğitimi ve Halk Oyunları',1),(7,'Oyun ve Taktiksel Farkındalık',2),(7,'Çocuklarda Atletik Performans Uygulamaları',2),(7,'Kapsamlı Spor Eğitimi',3),(8,'Beden Eğitimi ve Sporun Temelleri',1),(8,'Ritim Eğitimi ve Halk Oyunları',1),(8,'Oyun ve Taktiksel Farkındalık',2),(8,'Çocuklarda Atletik Performans Uygulamaları',2),(8,'Kapsamlı Spor Eğitimi',4)) insert into official_general_timetable_rows(profile_id,course_id,weekly_hours,category,source_page,constraints,active) select p.id,c.id,d.h,'uygulama',11,'{"program_pool":"SPOR"}',true from d join official_general_timetable_profiles p on p.school_type='IMAM_HATIP_ORTAOKULU' and p.program_variant='SPOR' and p.grade_level=d.g and p.active join course_catalog c on c.name=d.n;
commit;